import { expect, it } from "vitest";
import { MemoryFileSystem } from "@poe-code/safe-fs/core";
import { createCommandArguments } from "safe-bash-contracts/command";
import { createMagickCommand, runMagickCli, runMagickCliSync } from "./index.js";

// Fixed native ImageMagick 7.1.2-35 Q16-HDRI fixtures; inputs are not generated by this codec.
const cases = [
    { name: "default 2x2", options: [], coder: "yuv", input: "4c961dff00975b5a5c989b97", output: "73450dffbb8a72ff3f082effffe6ffff270000ffbc8b73ff7d466cff7b4185ff" },
    { name: "explicit 2x2", options: ["-sampling-factor", "2x2"], coder: "yuv", input: "4c961dff00975b5a5c989b97", output: "73450dffbb8a72ff3f082effffe6ffff270000ffbc8b73ff7d466cff7b4185ff" },
    { name: "packed 2x1", options: ["-sampling-factor", "2x1"], coder: "yuv", input: "5b4c8596aa1d67ff5e00b097855bc75a", output: "54550bff939d78ff052145ffddffffff440000ffe3786dffb72e53ffbe2564ff" },
    { name: "reset sampling", options: ["-sampling-factor", "2x1", "+sampling-factor"], coder: "yuv", input: "4c961dff00975b5a5c989b97", output: "73450dffbb8a72ff3f082effffe6ffff270000ffbc8b73ff7d466cff7b4185ff" },
    { name: "RGB control", options: [], coder: "rgb", input: "ff000000ff000000ffffffff000000ff8000fe0180804080", output: "ff0000ff00ff00ff0000ffffffffffff000000ffff8000fffe0180ff804080ff" },
];
for (const mode of ["command", "stream", "retained", "buffered", "sync"] as const) {
    it.each(cases)(`${mode} reads $name with an explicit coder overriding the extension`, async ({ options, coder, input, output }) => {
        const bytes = Buffer.from(input, "hex"), fs = new MemoryFileSystem();
        await fs.writeFile("/in.ppm", bytes);
        const files = new Map([["/in.ppm", bytes]]);
        const args = ["-size", "4x2", "-depth", "8", ...options, `${coder}:${mode === "stream" ? "-" : "/in.ppm"}`, "-colorspace", "sRGB", "-depth", "8", "rgba:-"];
        const chunks: Uint8Array[] = [];
        let stderr = "";
        const result = mode === "command" || mode === "stream" ? await createMagickCommand().execute({
            command: "magick", args: createCommandArguments(args).args, cwd: "/", env: {}, fs,
            signal: new AbortController().signal,
            stdin: (async function* () { for (const byte of bytes) yield Uint8Array.of(byte); })(),
            stdout: { async write(chunk) { chunks.push(chunk.slice()); } },
            stderr: { async write(chunk) { stderr += new TextDecoder().decode(chunk); } },
        }) : mode === "retained" ? await runMagickCli(args, { filesystem: fs, cwd: "/" })
            : mode === "buffered" ? await runMagickCli(args, files) : runMagickCliSync(args, files);
        if ("stdoutBytes" in result && result.stdoutBytes instanceof Uint8Array) chunks.push(result.stdoutBytes);
        if ("stderr" in result) stderr = result.stderr as string;
        expect(result.exitCode, stderr).toBe(0);
        expect(stderr).toBe("");
        expect(Buffer.concat(chunks).toString("hex")).toBe(output);
        expect(Buffer.from(await fs.readFile("/in.ppm")).toString("hex")).toBe(input);
    });
}

for (const mode of ["retained", "buffered", "sync"] as const) {
    it(`${mode} reads uppercase YUV extensions and selected frames after a byte offset`, async () => {
        const bytes = Buffer.from(`aabb${cases[0]!.input}${cases[0]!.input}`, "hex");
        const fs = new MemoryFileSystem(), files = new Map([["/in.YUV", bytes]]);
        await fs.writeFile("/in.YUV", bytes);
        const args = ["-size", "4x2+2", "-depth", "8", "/in.YUV[1]", "-colorspace", "sRGB", "rgba:-"];
        const result = mode === "sync" ? runMagickCliSync(args, files)
            : await runMagickCli(args, mode === "retained" ? { filesystem: fs, cwd: "/" } : files);
        expect(result).toMatchObject({ exitCode: 0, stderr: "" });
        expect(Buffer.from(result.stdoutBytes!).toString("hex")).toBe(cases[0]!.output);
    });

    it.each([
        { name: "missing size", args: ["-depth", "8"], input: cases[0]!.input, error: "must specify image size" },
        { name: "truncated frame", args: ["-size", "4x2", "-depth", "8"], input: cases[0]!.input.slice(0, -2), error: "unexpected end-of-file" },
        { name: "invalid sampling", args: ["-size", "4x2", "-depth", "8", "-sampling-factor", "3x2"], input: cases[0]!.input, error: "Unexpected sampling factor" },
    ])(`${mode} rejects $name without replacing the destination`, async ({ args, input, error }) => {
        const bytes = Buffer.from(input, "hex"), sentinel = Uint8Array.of(10, 20, 30);
        const fs = new MemoryFileSystem(), files = new Map<string, Uint8Array>([["/in.ppm", bytes], ["/out.rgba", sentinel]]);
        for (const [path, data] of files) await fs.writeFile(path, data);
        const argv = [...args, "yuv:/in.ppm", "-colorspace", "sRGB", "/out.rgba"];
        const result = mode === "sync" ? runMagickCliSync(argv, files)
            : await runMagickCli(argv, mode === "retained" ? { filesystem: fs, cwd: "/" } : files);
        expect(result.exitCode).not.toBe(0);
        expect(result.stderr).toContain(error);
        expect(mode === "retained" ? await fs.readFile("/out.rgba") : files.get("/out.rgba")).toEqual(sentinel);
    });
}

it.each([cases[0]!, cases[2]!])("reads big-endian 16-bit $name samples", async ({ input, output, options }) => {
    // Repeating each byte preserves the native 8-bit fixture's normalized samples at 16 bits.
    const bytes = Uint8Array.from([...Buffer.from(input, "hex")].flatMap(byte => [byte, byte]));
    const fs = new MemoryFileSystem();
    await fs.writeFile("/in.yuv", bytes);
    const result = await runMagickCli(["-size", "4x2", "-depth", "16", ...options, "/in.yuv", "-colorspace", "sRGB", "-depth", "8", "rgba:-"], { filesystem: fs, cwd: "/" });
    expect(result).toMatchObject({ exitCode: 0, stderr: "" });
    expect(Buffer.from(result.stdoutBytes!).toString("hex")).toBe(output);
});
